"use client";

import React, { useState, useMemo, useRef, useEffect } from "react";
import { 
  Calendar as CalendarIcon, ChevronDown, CheckCircle2, UploadCloud, 
  Plane, Stethoscope, Briefcase, Baby, Umbrella, Heart, AlertOctagon, 
  Trash2, ArrowRight, User, AlertTriangle, RefreshCcw, Sparkles, 
  Clock, RotateCcw, ChevronLeft, ChevronRight, Info
} from "lucide-react";

// --- Types & Config ---
const LEAVE_TYPES = [
  { id: "annual", label: "Annual", icon: Plane, balance: 18, color: "text-blue-500", bg: "bg-blue-500/10", requiresDoc: false },
  { id: "sick", label: "Sick", icon: Stethoscope, balance: 12, color: "text-rose-500", bg: "bg-rose-500/10", requiresDoc: true },
  { id: "casual", label: "Casual", icon: Briefcase, balance: 6, color: "text-amber-500", bg: "bg-amber-500/10", requiresDoc: false },
];

/**
 * IMPROVISED COMPONENT
 */
export default function IfBashLeavePortal() {
  // Navigation State
  const [currentDate, setCurrentDate] = useState(new Date(2026, 0, 1));
  const [mode, setMode] = useState<"single" | "range" | "multi">("range");
  
  // Selection State
  const [range, setRange] = useState<{ start: string; end: string }>({ start: "", end: "" });
  const [multiDates, setMultiDates] = useState<string[]>([]);
  const [isHalfDay, setIsHalfDay] = useState(false);
  
  // Form State
  const [typeId, setTypeId] = useState("annual");
  const [reason, setReason] = useState("");
  const [file, setFile] = useState<File | null>(null);

  // --- Derived Calculations ---
  const selectedType = useMemo(() => LEAVE_TYPES.find(t => t.id === typeId)!, [typeId]);

  const leaveStats = useMemo(() => {
    let count = 0;
    if (mode === "multi") count = multiDates.length;
    else if (range.start && range.end) {
      const s = new Date(range.start);
      const e = new Date(range.end);
      count = Math.ceil((e.getTime() - s.getTime()) / (1000 * 60 * 60 * 24)) + 1;
    } else if (range.start) count = 1;

    const finalDeduction = isHalfDay ? count * 0.5 : count;
    const isOverBalance = finalDeduction > selectedType.balance;

    return { count, finalDeduction, isOverBalance };
  }, [range, multiDates, mode, isHalfDay, selectedType]);

  // --- Render Helpers ---
  const daysInMonth = new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 0).getDate();
  const firstDay = (new Date(currentDate.getFullYear(), currentDate.getMonth(), 1).getDay() + 6) % 7;

  return (
    <div className="h-screen w-full bg-slate-50 dark:bg-[#080808] flex flex-col font-sans antialiased overflow-hidden">
      
      {/* 1. TOP NAV */}
      <header className="h-16 border-b border-slate-200 dark:border-white/5 bg-white dark:bg-[#111] px-6 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-indigo-600 rounded-lg shadow-indigo-500/20 shadow-lg">
            <CalendarIcon className="text-white h-5 w-5" />
          </div>
          <div>
            <h1 className="text-sm font-bold dark:text-white">Leave Management</h1>
            <p className="text-[10px] text-slate-500 font-medium">IfBash Employee Hub</p>
          </div>
        </div>
        <div className="flex gap-4">
           {LEAVE_TYPES.map(t => (
             <div key={t.id} className="flex flex-col items-end">
               <span className="text-[9px] uppercase font-bold text-slate-400">{t.label}</span>
               <span className="text-xs font-bold dark:text-slate-200">{t.balance}d</span>
             </div>
           ))}
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden p-4 gap-4">
        
        {/* 2. CALENDAR SECTION */}
        <div className="flex-1 bg-white dark:bg-[#111] rounded-2xl border border-slate-200 dark:border-white/5 flex flex-col shadow-sm">
          <div className="p-4 border-b border-slate-50 dark:border-white/5 flex items-center justify-between">
            <div className="flex bg-slate-100 dark:bg-white/5 p-1 rounded-xl">
              {['single', 'range', 'multi'].map(m => (
                <button 
                  key={m} 
                  onClick={() => {setMode(m as any); setRange({start:"", end:""}); setMultiDates([])}}
                  className={`px-4 py-1.5 rounded-lg text-[11px] font-bold capitalize transition-all ${mode === m ? 'bg-white dark:bg-[#222] text-indigo-600 shadow-sm' : 'text-slate-500'}`}
                >
                  {m}
                </button>
              ))}
            </div>
            
            <div className="flex items-center gap-2">
              <button onClick={() => setCurrentDate(new Date(currentDate.setMonth(currentDate.getMonth()-1)))} className="p-2 hover:bg-slate-100 dark:hover:bg-white/5 rounded-full"><ChevronLeft className="h-4 w-4"/></button>
              <span className="text-sm font-bold min-w-[120px] text-center">{currentDate.toLocaleString('default', { month: 'long', year: 'numeric' })}</span>
              <button onClick={() => setCurrentDate(new Date(currentDate.setMonth(currentDate.getMonth()+1)))} className="p-2 hover:bg-slate-100 dark:hover:bg-white/5 rounded-full"><ChevronRight className="h-4 w-4"/></button>
            </div>
          </div>

          <div className="flex-1 p-6 grid grid-cols-7 gap-2 auto-rows-fr">
            {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => (
              <div key={d} className="text-center text-[10px] font-bold text-slate-400 uppercase">{d}</div>
            ))}
            {Array.from({ length: firstDay }).map((_, i) => <div key={i} />)}
            {Array.from({ length: daysInMonth }).map((_, i) => {
              const d = i + 1;
              const dateStr = `2026-${String(currentDate.getMonth()+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
              const isSelected = mode === 'multi' ? multiDates.includes(dateStr) : (range.start === dateStr || range.end === dateStr);
              const inRange = range.start && range.end && dateStr > range.start && dateStr < range.end;

              return (
                <button 
                  key={d}
                  onClick={() => {
                    if(mode === 'multi') setMultiDates(prev => prev.includes(dateStr) ? prev.filter(x => x !== dateStr) : [...prev, dateStr]);
                    else if(!range.start || (range.start && range.end)) setRange({start: dateStr, end: ""});
                    else setRange(prev => dateStr < prev.start ? {start: dateStr, end: prev.start} : {...prev, end: dateStr});
                  }}
                  className={`relative rounded-xl border transition-all flex flex-col p-2 items-start justify-between
                    ${isSelected ? 'bg-indigo-600 border-indigo-600 text-white shadow-md z-10 scale-105' : 
                      inRange ? 'bg-indigo-50 dark:bg-indigo-900/20 border-indigo-100 dark:border-indigo-800/50 text-indigo-600' : 
                      'bg-white dark:bg-white/5 border-slate-100 dark:border-white/5 hover:border-indigo-300'}
                  `}
                >
                  <span className="text-xs font-bold">{d}</span>
                </button>
              );
            })}
          </div>
        </div>

        {/* 3. REQUEST PANEL */}
        <aside className="w-[380px] flex flex-col gap-4">
          <div className="bg-white dark:bg-[#111] rounded-2xl border border-slate-200 dark:border-white/5 p-5 flex flex-col gap-5 shadow-xl">
            
            {/* Type Selector */}
            <div>
              <label className="text-[10px] font-bold text-slate-400 uppercase mb-2 block tracking-widest">Absence Category</label>
              <div className="grid grid-cols-3 gap-2">
                {LEAVE_TYPES.map(t => (
                  <button 
                    key={t.id} 
                    onClick={() => setTypeId(t.id)}
                    className={`p-3 rounded-xl border flex flex-col items-center gap-2 transition-all ${typeId === t.id ? 'border-indigo-500 bg-indigo-500/5 ring-1 ring-indigo-500' : 'border-slate-100 dark:border-white/5'}`}
                  >
                    <t.icon className={`h-4 w-4 ${t.color}`} />
                    <span className="text-[10px] font-bold">{t.label}</span>
                  </button>
                ))}
              </div>
            </div>

            {/* Dynamic Half-Day Toggle */}
            {mode === 'single' && (
              <div className="flex items-center justify-between p-3 bg-slate-50 dark:bg-white/5 rounded-xl border border-slate-100 dark:border-white/5">
                <div className="flex items-center gap-2">
                  <div className="p-1.5 bg-amber-100 dark:bg-amber-900/30 rounded-lg"><Clock className="h-3 w-3 text-amber-600" /></div>
                  <span className="text-xs font-bold">Half Day Session</span>
                </div>
                <button 
                  onClick={() => setIsHalfDay(!isHalfDay)}
                  className={`w-10 h-5 rounded-full relative transition-colors ${isHalfDay ? 'bg-indigo-600' : 'bg-slate-300'}`}
                >
                  <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${isHalfDay ? 'left-6' : 'left-1'}`} />
                </button>
              </div>
            )}

            {/* Stats Summary */}
            <div className="bg-slate-900 rounded-xl p-4 text-white flex justify-between items-center overflow-hidden relative">
              <div className="relative z-10">
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tight">Total Deduction</p>
                <h3 className="text-2xl font-black">{leaveStats.finalDeduction} Days</h3>
              </div>
              <div className={`h-12 w-12 rounded-full border-4 flex items-center justify-center font-bold text-xs ${leaveStats.isOverBalance ? 'border-rose-500 text-rose-500' : 'border-indigo-500 text-indigo-500'}`}>
                {selectedType.balance - leaveStats.finalDeduction}
              </div>
              <Sparkles className="absolute -right-2 -bottom-2 h-16 w-16 text-white/5" />
            </div>

            {leaveStats.isOverBalance && (
              <div className="p-3 bg-rose-50 dark:bg-rose-900/20 border border-rose-100 dark:border-rose-800 rounded-xl flex items-start gap-2 animate-pulse">
                <AlertOctagon className="h-4 w-4 text-rose-500 shrink-0 mt-0.5" />
                <p className="text-[10px] font-bold text-rose-700 dark:text-rose-400">Insufficent balance. This will be marked as Loss of Pay (L.O.P).</p>
              </div>
            )}

            <div className="space-y-4">
              <textarea 
                placeholder="Why are you taking this leave?"
                className="w-full bg-slate-50 dark:bg-white/5 border border-slate-100 dark:border-white/10 rounded-xl p-3 text-xs min-h-[80px] focus:ring-2 ring-indigo-500 outline-none"
                value={reason}
                onChange={(e) => setReason(e.target.value)}
              />
              
              <button 
                disabled={!reason || (mode === 'range' && !range.end)}
                className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-200 dark:disabled:bg-white/5 disabled:text-slate-400 text-white rounded-xl font-bold text-sm transition-all shadow-lg shadow-indigo-500/25 active:scale-95"
              >
                Send Request to Manager
              </button>
            </div>
          </div>
        </aside>
      </main>
    </div>
  );
}